  var t = (a - H_THRESHOLD) / (B_THRESHOLD - H_THRESHOLD);
  var off = 28 + t * 122;
  if (state.caseName !== 'twoTriangles') off = 118;
  var leftX = C.foot - off, rightX = C.foot + off;
  var color = state.caseName === 'twoTriangles' ? '#1458b3' : '#000';
  var width = state.caseName === 'twoTriangles' ? 5 : 4;
