function updateHighlights() {
  var names = ['noTriangle', 'rightTriangle', 'twoTriangles', 'oneTriangle'];
  for (var i = 0; i < names.length; i++) {
    var p = panels[names[i]];
    var active = names[i] === state.caseName;
    p.highlight.fill({ color: '#4da3ff', opacity: active ? 0.13 : 0 });
    p.highlight.stroke({ color: '#2276d2', width: active ? 4 : 0, opacity: active ? 0.95 : 0 });
  }

  var aBottom = A.gy + Math.min(state.a / H_THRESHOLD, 0.98) * (A.ay - A.gy);
  if (state.caseName === 'noTriangle') {
    panels.noTriangle.aSide.plot(A.gx, A.gy, A.gx, aBottom).stroke({ color: '#000', width: 4 });
    panels.noTriangle.gap.plot(A.gx, aBottom + 3, A.gx, A.ay).attr({ opacity: 1 });
  } else {
    panels.noTriangle.aSide.plot(A.gx, A.gy, A.gx, 326).stroke({ color: '#000', width: 4 });
