makeInteractive(panels.noTriangle.group, 'a < h: no triangle', 'No triangle: a < h',
  'Side a is shorter than the altitude h, so it cannot reach the base line. Since no landing point exists, no triangle can be formed.');
makeInteractive(panels.rightTriangle.group, 'a = h: right triangle', 'Right triangle: a = h',
  'Side a just reaches the base at the perpendicular foot. There is exactly one possible triangle, and it is a right triangle.');
makeInteractive(panels.twoTriangles.group, 'h < a < b: two triangles', 'Two triangles: h < a < b',
  'Side a is long enough to reach the base but shorter than b. It can land on either side of the altitude foot, creating two different triangles.');
makeInteractive(panels.oneTriangle.group, 'a ≥ b: one triangle', 'One triangle: a ≥ b',
  'When a is at least as long as b, the alternate landing no longer gives a second valid SSA triangle. Only the oblique triangle remains.');

syncUi();
updateHighlights();
window.__markRendered();
// @FIGURE_CODE_END

