function addLine(parent, x1, y1, x2, y2, stroke, width) {
  return parent.line(x1, y1, x2, y2).stroke({
    color: stroke || '#000',
    width: width || 4,
    linecap: 'butt',
    linejoin: 'miter'
  });
}

function addText(parent, s, x, y, size, opts) {
  opts = opts || {};
  var t = parent.text(s).move(x, y);
  t.font({
    family: opts.family || 'Times New Roman, Times, serif',
    size: size || 34,
    style: opts.style || 'italic',
    weight: opts.weight || 'normal',
    anchor: opts.anchor || 'start'
  });
  t.fill(opts.fill || '#000');
  t.attr({
    'paint-order': 'stroke',
    stroke: opts.halo === false ? 'none' : '#fff',
    'stroke-width': opts.halo === false ? 0 : 4,
    'stroke-linejoin': 'round'
  });
  return t;
}

