function arcPath(ax, ay, gx, gy, r) {
  var dx = gx - ax, dy = gy - ay;
  var len = Math.sqrt(dx * dx + dy * dy);
  var ex = ax + r * dx / len;
  var ey = ay + r * dy / len;
  return 'M ' + (ax + r) + ' ' + ay + ' A ' + r + ' ' + r + ' 0 0 0 ' + ex + ' ' + ey;
}

function addAngleArc(parent, ax, ay, gx, gy, r) {
  return parent.path(arcPath(ax, ay, gx, gy, r)).fill('none').stroke({ color: '#000', width: 3 });
}

function addRightSquare(parent, x, y, side, orientation) {
  if (orientation === 'left') {
    return parent.path('M ' + (x - side) + ' ' + y + ' L ' + (x - side) + ' ' + (y - side) + ' L ' + x + ' ' + (y - side))
      .fill('none').stroke({ color: '#000', width: 3 });
  }
  return parent.path('M ' + (x + side) + ' ' + y + ' L ' + (x + side) + ' ' + (y - side) + ' L ' + x + ' ' + (y - side))
    .fill('none').stroke({ color: '#000', width: 3 });
}

