function classifyA(v) {
  if (Math.abs(v - H_THRESHOLD) <= 0.012) return 'rightTriangle';
  if (v < H_THRESHOLD) return 'noTriangle';
  if (v < B_THRESHOLD) return 'twoTriangles';
  return 'oneTriangle';
}

function casePhrase(name) {
  if (name === 'noTriangle') return 'no triangle';
  if (name === 'rightTriangle') return 'one right triangle';
  if (name === 'twoTriangles') return 'two triangles';
  return 'one triangle';
}

function redrawTwoTriangleDashed() {
  panels.twoTriangles.dashGroup.clear();
  var a = Math.max(H_THRESHOLD, Math.min(B_THRESHOLD, state.a));
  var t = (a - H_THRESHOLD) / (B_THRESHOLD - H_THRESHOLD);
  var off = 42 + t * 84;
  if (state.caseName !== 'twoTriangles') off = 104;
  var leftX = C.foot - off;
  var rightX = C.foot + off;
  var l1 = addLine(panels.twoTriangles.dashGroup, C.gx, C.gy, leftX, C.ay, '#000', 4).attr({ 'stroke-dasharray': '15 12' });
  var l2 = addLine(panels.twoTriangles.dashGroup, C.gx, C.gy, rightX, C.ay, '#000', 4).attr({ 'stroke-dasharray': '15 12' });
  makeInteractive(l1, 'First possible side a', 'First landing for a',
    'For h < a < b, a circle centered at γ with radius a cuts the base in two places.');
  makeInteractive(l2, 'Second possible side a', 'Second landing for a',
    'The second landing gives a different triangle with the same SSA data.');
}

function updateHighlights() {
