  for (var i = 0; i < names.length; i++) {
    var p = panels[names[i]];
    var active = state.userActive && names[i] === state.caseName;
    p.highlight.fill({ color: '#ffe9a8', opacity: active ? 0.18 : 0 });
    p.highlight.stroke({ color: '#d49a00', width: active ? 4 : 0, opacity: active ? 0.9 : 0 });
  }

  var aBottom = A.gy + Math.min(state.a / H_THRESHOLD, 0.98) * (A.ay - A.gy);
  if (state.caseName === 'noTriangle') {
    panels.noTriangle.aSide.plot(A.gx, A.gy, A.gx, aBottom).stroke({ color: '#000', width: 4.2 });
