function update_sideLengthA(v) {
  state.userActive = true;
  state.a = v;
  state.caseName = classifyA(v);
  syncUi();
  updateHighlights();
}

function toggle_showAltitude(on) {
  state.userActive = true;
  state.showAltitude = !!on;
  syncUi();
  updateHighlights();
}

function setCaseStep(name) {
  state.userActive = true;
  if (!caseValues.hasOwnProperty(name)) name = classifyA(state.a);
  state.caseName = name;
  state.a = caseValues[name];
  for (var i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.caseStep === name && demoSteps[i].state.showAltitude === state.showAltitude) {
      state.step = i;
      break;
    }
  }
  syncUi();
  updateHighlights();
}

function applyDemoStep(i, activated) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  if (activated) state.userActive = true;
  var s = demoSteps[state.step].state;
  state.a = s.sideLengthA;
  state.showAltitude = s.showAltitude;
  state.caseName = s.caseStep;
  syncUi();
  updateHighlights();
}

function nextStep() {
  applyDemoStep(state.step + 1, true);
}

function prevStep() {
  applyDemoStep(state.step - 1, true);
}

syncUi();
updateHighlights();
