  return t;
}

function titleSize(text, w, isStacked) {
  var guess = isStacked ? 33 : 36;
  return Math.max(23, Math.min(guess, (w - 18) / (text.length * 0.50)));
}

function addHeading(parent, s, cx, y, w, stacked) {
  return addText(parent, s, cx, y, titleSize(s, w, stacked), {
    anchor: 'middle',
    style: 'normal',
    halo: true
  });
}

function angleArc(parent, ax, ay, r) {
  var ex = ax + COS_A * r;
  var ey = ay - SIN_A * r;
  return parent.path('M ' + (ax + r) + ' ' + ay + ' A ' + r + ' ' + r + ' 0 0 0 ' + ex + ' ' + ey)
    .fill('none')
    .stroke({ color: '#000', width: 3.2, linecap: 'round' });
}

function rightSquare(parent, x, y, side, dir) {
  dir = dir || 'left';
  if (dir === 'right') {
    return parent.path('M ' + x + ' ' + (y - side) + ' L ' + (x + side) + ' ' + (y - side) + ' L ' + (x + side) + ' ' + y)
      .fill('none').stroke({ color: '#000', width: 3.1 });
  }
  return parent.path('M ' + (x - side) + ' ' + y + ' L ' + (x - side) + ' ' + (y - side) + ' L ' + x + ' ' + (y - side))
    .fill('none').stroke({ color: '#000', width: 3.1 });
}

function makeInteractive(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function midpointLabel(parent, s, x1, y1, x2, y2, dx, dy, size) {
  return addText(parent, s, (x1 + x2) / 2 + (dx || 0), (y1 + y2) / 2 + (dy || 0), size || 33);
}

function addOverlay(parent, r, tip, title, body) {
  var ov = parent.rect(r.w, r.h).move(r.x, r.y).fill({ color: '#fff', opacity: 0 });
  ov.attr({ 'pointer-events': 'all' });
  makeInteractive(ov, tip, title, body);
}

function panelHighlight(parent, r, active) {
  parent.rect(r.w - 4, r.h - 4).move(r.x + 2, r.y + 2).radius(12)
    .fill({ color: '#ffe9a8', opacity: active ? 0.16 : 0 })
    .stroke({ color: '#d49a00', width: active ? 4 : 0, opacity: active ? 0.92 : 0 });
}

function panelScale(r, kind) {
  var titleReserve = 66;
  var markerReserve = 43;
  var availH = r.h - titleReserve - markerReserve;
  var baseY = r.y + r.h - markerReserve;
  var desiredW;
  if (kind === 'twoTriangles') desiredW = 1.47;
  else if (kind === 'oneTriangle') desiredW = 1.92;
  else desiredW = 1.02;
  var s = Math.min(availH / 0.78, (r.w * 0.80) / desiredW);
  s = Math.max(105, s);
  return { s: s, baseY: baseY, topY: r.y + titleReserve };
}

function drawNoTriangle(parent, labels, r, active, stacked) {
  panelHighlight(parent, r, active);
  addHeading(labels, 'No triangle, a < h', r.x + r.w / 2, r.y + 7, r.w, stacked);

  var ps = panelScale(r, 'noTriangle');
  var s = ps.s, ay = ps.baseY;
  var ax = r.x + r.w * 0.11;
  var gx = ax + COS_A * s;
  var gy = ay - SIN_A * s;
  var foot = gx;
  var aLen = active ? Math.min(state.a, H_THRESHOLD - 0.015) : 0.40;
  var aEnd = gy + aLen * s;

  addLine(parent, ax, ay, foot, ay);
  makeInteractive(addLine(parent, ax, ay, gx, gy), 'Known side b', 'Known side b', 'Side b and the acute angle α are fixed. The number of possible SSA triangles changes only when side a changes.');
  makeInteractive(addLine(parent, gx, gy, gx, aEnd), 'Candidate side a is too short', 'a < h: no triangle', 'The side of length a stops above the base line, so it cannot close a triangle.');
  if (active) {
    addLine(parent, gx + 10, aEnd + 8, gx + 10, ay - 3, '#d08a00', 5);
  }
  angleArc(parent, ax, ay, Math.min(56, s * 0.18));

  addText(labels, 'α', ax - 27, ay - 5, 34);
  addText(labels, 'β', foot + 21, ay - 5, 34);
  addText(labels, 'γ', gx - 5, gy - 40, 34);
  midpointLabel(labels, 'b', ax, ay, gx, gy, -18, -1, 33);
  midpointLabel(labels, 'a', gx, gy, gx, aEnd, 18, -3, 33);
  addText(labels, '(a)', r.x + r.w / 2, ay + 14, 34, { anchor: 'middle', style: 'normal' });

  addOverlay(parent, r, 'a < h: no triangle', 'No triangle: a < h', 'The altitude h is the shortest distance from γ to the base line. When a is smaller than h, the candidate side cannot reach the base at all.');
}

function drawRightTriangle(parent, labels, r, active, stacked) {
  panelHighlight(parent, r, active);
  addHeading(labels, 'Right triangle, a = h', r.x + r.w / 2, r.y + 7, r.w, stacked);

  var ps = panelScale(r, 'rightTriangle');
  var s = ps.s, ay = ps.baseY;
  var ax = r.x + r.w * 0.11;
  var gx = ax + COS_A * s;
  var gy = ay - SIN_A * s;
  var beta = gx;

  addLine(parent, ax, ay, beta, ay);
  makeInteractive(addLine(parent, ax, ay, gx, gy), 'Known side b', 'Known side b', 'The fixed side b sets the height h = b sin(α), the reach threshold for side a.');
  makeInteractive(addLine(parent, gx, gy, beta, ay, active ? '#d08a00' : '#000', active ? 5 : 4.2), 'a equals the altitude h', 'a = h: one right triangle', 'Side a reaches exactly the perpendicular foot, giving one triangle with a right angle at β.');
  rightSquare(parent, beta, ay, Math.min(42, s * 0.15), 'left').stroke({ color: active ? '#d08a00' : '#000', width: active ? 3.8 : 3.1 });
  angleArc(parent, ax, ay, Math.min(56, s * 0.18));

  addText(labels, 'α', ax - 27, ay - 5, 34);
  addText(labels, 'β', beta + 21, ay - 5, 34);
  addText(labels, 'γ', gx - 5, gy - 40, 34);
  midpointLabel(labels, 'b', ax, ay, gx, gy, -18, -1, 33);
  midpointLabel(labels, 'a', gx, gy, beta, ay, 18, -3, 33);
  addText(labels, '(b)', r.x + r.w / 2, ay + 14, 34, { anchor: 'middle', style: 'normal' });

  addOverlay(parent, r, 'a = h: right triangle', 'Right triangle: a = h', 'At exactly the altitude, the circle centered at γ with radius a is tangent to the base. A single right triangle is possible.');
}

function drawTwoTriangles(parent, labels, r, active, stacked) {
  panelHighlight(parent, r, active);
  addHeading(labels, 'Two triangles, a > h, a < b', r.x + r.w / 2, r.y + 7, r.w, stacked);

  var ps = panelScale(r, 'twoTriangles');
  var s = ps.s, ay = ps.baseY;
  var ax = r.x + r.w * 0.09;
  var gx = ax + COS_A * s;
  var gy = ay - SIN_A * s;
  var aNow = active ? Math.max(H_THRESHOLD + 0.025, Math.min(state.a, B_THRESHOLD - 0.025)) : 0.80;
  var off = Math.sqrt(Math.max(0, aNow * aNow - H_THRESHOLD * H_THRESHOLD)) * s;
  var leftX = gx - off;
  var rightX = gx + off;
  var baseEnd = rightX;

  addLine(parent, ax, ay, baseEnd, ay);
  makeInteractive(addLine(parent, ax, ay, gx, gy), 'Known side b', 'Known side b', 'Side b is the comparison length that separates the two-triangle case from the one-oblique-triangle case.');
  if (state.showAltitude) {
    makeInteractive(addLine(parent, gx, gy, gx, ay), 'Altitude h = b sin(α)', 'Altitude h', 'The altitude is the shortest possible reach from γ to the base. It explains why a must be at least h before any triangle can form.');
    addText(labels, 'h', gx + 17, gy + (ay - gy) * 0.67, 34);
    rightSquare(parent, gx, ay, Math.min(35, s * 0.12), 'right');
  }

  makeInteractive(addLine(parent, gx, gy, leftX, ay, active ? '#d08a00' : '#000', active ? 5 : 4.2, '16 12'), 'First possible side a', 'First landing for a', 'For h < a < b, the radius a from γ cuts the base in two places.');
  makeInteractive(addLine(parent, gx, gy, rightX, ay, active ? '#d08a00' : '#000', active ? 5 : 4.2, '16 12'), 'Second possible side a', 'Second landing for a', 'The second landing creates a different triangle with the same SSA information.');

  angleArc(parent, ax, ay, Math.min(56, s * 0.18));
  addText(labels, 'α', ax - 27, ay - 5, 34);
  addText(labels, 'β', baseEnd + 21, ay - 5, 34);
  addText(labels, 'γ', gx - 5, gy - 40, 34);
  midpointLabel(labels, 'b', ax, ay, gx, gy, -18, -1, 33);
  midpointLabel(labels, 'a', gx, gy, leftX, ay, -20, -12, 33);
  midpointLabel(labels, 'a', gx, gy, rightX, ay, 22, -11, 33);
  addText(labels, '(c)', r.x + r.w / 2, ay + 14, 34, { anchor: 'middle', style: 'normal' });

  addOverlay(parent, r, 'h < a < b: two triangles', 'Two triangles: h < a < b', 'Here a is long enough to reach the base but not as long as b. The same side length can land on either side of the altitude, producing two distinct triangles.');
}

function drawOneTriangle(parent, labels, r, active, stacked) {
  panelHighlight(parent, r, active);
  addHeading(labels, 'One triangle, a ≥ b', r.x + r.w / 2, r.y + 7, r.w, stacked);

  var ps = panelScale(r, 'oneTriangle');
  var s = ps.s, ay = ps.baseY;
  var ax = r.x + r.w * 0.08;
  var gx = ax + COS_A * s;
  var gy = ay - SIN_A * s;
  var aDraw = Math.max(active ? state.a : 1.14, 1.14);
  var offRight = Math.sqrt(Math.max(0, aDraw * aDraw - H_THRESHOLD * H_THRESHOLD)) * s;
  var beta = gx + offRight;

  addLine(parent, ax, ay, beta, ay);
  makeInteractive(addLine(parent, ax, ay, gx, gy), 'Known side b', 'Known side b', 'When the candidate side is at least this long, the ambiguous second closure disappears.');
  makeInteractive(addLine(parent, gx, gy, beta, ay, active ? '#d08a00' : '#000', active ? 5 : 4.2), 'Single possible side a, with a ≥ b', 'a ≥ b: one triangle', 'With a at least as long as b, only the farther base landing gives a valid oblique triangle.');
  angleArc(parent, ax, ay, Math.min(56, s * 0.18));

  addText(labels, 'α', ax - 27, ay - 5, 34);
  addText(labels, 'β', beta + 21, ay - 5, 34);
  addText(labels, 'γ', gx - 5, gy - 40, 34);
  midpointLabel(labels, 'b', ax, ay, gx, gy, -18, -1, 33);
  midpointLabel(labels, 'a', gx, gy, beta, ay, 22, -4, 33);
  addText(labels, '(d)', r.x + r.w / 2, ay + 14, 34, { anchor: 'middle', style: 'normal' });

  addOverlay(parent, r, 'a ≥ b: one triangle', 'One triangle: a ≥ b', 'The side labeled a is drawn perceptibly at least as long as b. In this range the SSA data determine a single oblique triangle.');
}

function render() {
  var sz = containerSize();
  var aspect = sz.w / sz.h;
  var stacked = aspect < 2.55;
  var W = stacked ? 1200 : 1920;
  var H = stacked ? 790 : 455;
  draw.viewbox(0, 0, W, H);
  draw.clear();

  var geom = draw.group();
  var labels = draw.group();

  if (stacked) {
    var gapX = 26, gapY = 24;
    var pw = (W - gapX * 3) / 2;
    var ph = (H - gapY * 3) / 2;
    drawNoTriangle(geom, labels, { x: gapX, y: gapY, w: pw, h: ph }, state.caseName === 'noTriangle', true);
    drawRightTriangle(geom, labels, { x: gapX * 2 + pw, y: gapY, w: pw, h: ph }, state.caseName === 'rightTriangle', true);
    drawTwoTriangles(geom, labels, { x: gapX, y: gapY * 2 + ph, w: pw, h: ph }, state.caseName === 'twoTriangles', true);
    drawOneTriangle(geom, labels, { x: gapX * 2 + pw, y: gapY * 2 + ph, w: pw, h: ph }, state.caseName === 'oneTriangle', true);
  } else {
    var y = 12, h = H - 24, gap = 22;
    var x0 = 18;
    var wA = 340, wB = 340, wC = 540, wD = 590;
    drawNoTriangle(geom, labels, { x: x0, y: y, w: wA, h: h }, state.caseName === 'noTriangle', false);
    drawRightTriangle(geom, labels, { x: x0 + wA + gap, y: y, w: wB, h: h }, state.caseName === 'rightTriangle', false);
    drawTwoTriangles(geom, labels, { x: x0 + wA + wB + gap * 2, y: y, w: wC, h: h }, state.caseName === 'twoTriangles', false);
    drawOneTriangle(geom, labels, { x: x0 + wA + wB + wC + gap * 3, y: y, w: wD, h: h }, state.caseName === 'oneTriangle', false);
  }

  labels.front();
}

function syncUi() {
  var slider = document.getElementById('sideLengthAInput');
  var out = document.getElementById('sideLengthAVal');
  var chk = document.getElementById('showAltitudeInput');
  var sel = document.getElementById('caseStepInput');
  if (slider) slider.value = state.a;
  if (out) out.value = state.a.toFixed(2);
  if (chk) chk.checked = !!state.showAltitude;
  if (sel) sel.value = state.caseName;

  var readout = document.getElementById('thresholdReadout');
  if (readout) {
    readout.textContent = 'a = ' + state.a.toFixed(2) + '; h = 0.60; b = 1.00 → ' + casePhrase(state.caseName);
  }
  var narr = document.getElementById('demoNarration');
  if (narr) narr.textContent = demoSteps[state.step].narration;
  var stepLabel = document.getElementById('stepLabel');
  if (stepLabel) stepLabel.textContent = 'Step ' + (state.step + 1) + ' / ' + demoSteps.length;
}

function update_sideLengthA(v) {
  state.a = v;
  state.caseName = classifyA(v);
  syncUi();
  render();
}

function toggle_showAltitude(on) {
  state.showAltitude = !!on;
  syncUi();
  render();
}

function setCaseStep(name) {
  if (!caseValues.hasOwnProperty(name)) name = classifyA(state.a);
  state.caseName = name;
  state.a = caseValues[name];
  for (var i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.caseStep === name && demoSteps[i].state.showAltitude === state.showAltitude) {
      state.step = i;
      break;
    }
  }
  syncUi();
  render();
}

function applyDemoStep(i) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  var s = demoSteps[state.step].state;
  state.a = s.sideLengthA;
  state.showAltitude = s.showAltitude;
  state.caseName = s.caseStep;
  syncUi();
  render();
}

function nextStep() {
  applyDemoStep(state.step + 1);
}

function prevStep() {
  applyDemoStep(state.step - 1);
}

document.addEventListener('fig-resize', function () {
  render();
});

applyDemoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

